// Coil functions stay independent of manufacturer lead colours. Model-specific entries may override a verified convention.
export const conductorRoles={hot:'northStart',linkA:'northFinish',linkB:'southFinish',ground:'southStart',shield:'shield'};
const generic={northStart:['#303b43','NORTH START / HOT'],northFinish:['#926f31','NORTH FINISH'],southFinish:['#926f31','SOUTH FINISH'],southStart:['#7a8187','SOUTH START / GROUND'],shield:['#999999','BARE SHIELD']};
export const pickupConventions={
 generic:{label:'Generic / Unspecified',verified:true,functions:generic,models:{}},
 duncan:{label:'Seymour Duncan · standard 4-conductor',verified:true,functions:{northStart:['#202020','BLACK'],northFinish:['#d7d7d7','WHITE'],southFinish:['#b91c1c','RED'],southStart:['#426d48','GREEN'],shield:['#999999','BARE']},source:'Seymour Duncan four-conductor technical documentation',models:{}},
 dimarzio:{label:'DiMarzio · standard 4-conductor',verified:true,functions:{northStart:['#b91c1c','RED'],northFinish:['#202020','BLACK'],southFinish:['#d7d7d7','WHITE'],southStart:['#426d48','GREEN'],shield:['#999999','BARE']},source:'DiMarzio official four-conductor FAQ',models:{}},
 gibson:{label:'Gibson · listed 4-conductor models',verified:true,functions:{northStart:['#b91c1c','RED'],northFinish:['#426d48','GREEN'],southFinish:['#d7d7d7','WHITE'],southStart:['#202020','BLACK'],shield:['#999999','SHIELD']},source:'Gibson four-conductor diagram, listed models only',models:{}},
 tonerider:{label:'Tonerider · standard 4-conductor',verified:true,functions:{northStart:['#b91c1c','RED'],northFinish:['#202020','BLACK'],southFinish:['#d7d7d7','WHITE'],southStart:['#426d48','GREEN'],shield:['#999999','BARE']},source:'Tonerider official pickup wiring colour codes',models:{}},
 warman:{label:'Warman · documented standard',verified:true,functions:{northStart:['#426d48','GREEN'],northFinish:['#b91c1c','RED'],southFinish:['#d7d7d7','WHITE'],southStart:['#202020','BLACK'],shield:['#999999','BARE']},source:'Warman official humbucker wire colour guidance',models:{}},
 'prs-se-neck':{label:'PRS SE 2021 diagram · neck',verified:true,functions:{northStart:['#202020','BLACK'],northFinish:['#426d48','GREEN'],southFinish:['#d7d7d7','WHITE'],southStart:['#b91c1c','RED'],shield:['#999','BARE']},source:'PRS SE V PP BLADE 2021 WEB, neck functional leads; magnetic polarity not inferred',models:{}},
 'prs-se-bridge':{label:'PRS SE 2021 diagram · bridge',verified:true,functions:{northStart:['#d7d7d7','WHITE'],northFinish:['#b91c1c','RED'],southFinish:['#202020','BLACK'],southStart:['#426d48','GREEN'],shield:['#999','BARE']},source:'PRS SE V PP BLADE 2021 WEB, bridge functional leads; magnetic polarity not inferred',models:{}},
 ...Object.fromEntries([['fender','Fender'],['prs','PRS'],['bareknuckle','Bare Knuckle']].map(([id,label])=>[id,{label,verified:false,status:id==='fender'?'requires-model':'unresolved',functions:null,models:{}}]))
};
export function resolveConvention(id,model){const base=pickupConventions[id]||{label:String(id),verified:false,status:'unresolved',models:{}},entry=base.models?.[model]||base,functions=entry.verified?entry.functions:generic;return {...entry,status:entry.status||(id==='generic'?'generic':'verified'),label:entry.label+(entry.verified?'':' · Colour code not yet verified; generic conductors shown'),wires:Object.fromEntries(Object.entries(conductorRoles).map(([role,fn])=>[role,functions[fn]]))};}
export const colourCodes=Object.fromEntries(Object.keys(pickupConventions).map(id=>[id,resolveConvention(id)]));
